116	impl<'src> SourceDataCollector<'src> {
117	    pub(super) fn promote_function_aliases(&mut self) {
118	        let aliases = std::mem::take(&mut self.pending_function_aliases);
119	        for _ in 0..aliases.len() {
120	            let mut changed = false;
121	            for (name, target) in &aliases {
122	                let key = self.scoped_key(name);
123	                if self.data.function_results.contains_key(&key) {
124	                    continue;
125	                }
126	                if let Some(result) = self.data.function_results.get(&self.scoped_key(target)).cloned() {
127	                    self.data.function_results.insert(key, result);
128	                    changed = true;
129	                }
130	            }
131	            if !changed {
132	                break;
133	            }
134	        }
135	    }
136	
137	    /// Record `const Name = callee<...>(first, ...)` as a candidate. Returns whether it was recorded.
138	    pub(super) fn try_record_wrapper_call<'a>(&mut self, decl: &super::component::Binding<'_, 'a>, name: &str) -> bool {
139	        let Some(init) = decl.init else { return false };
140	        let Expression::CallExpression(call) = super::component::peel_expr(init) else { return false };
141	        let Some(type_arguments) = call.type_arguments.as_ref() else { return false };
142	        let Some(callee) = self.extract_callee_name(call) else { return false };
143	        let creates_context = self.react_api(&call.callee) == Some(super::ReactApi::CreateContext);
144	        let needs_payload = match component_argument_evidence(creates_context, call, &*self) {
145	            Ok(ArgumentEvidence::Sufficient) => false,
146	            Ok(ArgumentEvidence::TagNeedsPayload) => true,
147	            Err(reason) => {
148	                self.decline_reason = Some(format!("'{name}' is a generic call to '{callee}' that {reason}"));
149	                self.argument_declined = !creates_context;
150	                return false;
151	            }
152	        };
153	        let type_args: Vec<WrapperTypeArg> = type_arguments
154	            .params
155	            .iter()
156	            .map(|ty| WrapperTypeArg { reference: self.extract_type_name_from_type(ty) })
157	            .collect();
158	        let Some(callee) = self.wrapper_callee(call) else { return false };
159	        let (description, tags) = self.find_jsdoc_with_tags(decl.span.start);
160	        self.pending_wrappers.push(PendingWrapper {
161	            name: name.to_owned(),
162	            needs_payload,
163	            tag: None,
164	            type_args,
165	            callee: Some(callee),
166	            rule: DetectionRule::WrapperTypeArgument,
167	            description,
168	            tags,
169	            span: decl.span,
170	        });
171	        true
172	    }
173	
174	    /// Record `const Center = chakra("div", { ... })` as a candidate: a call given an intrinsic tag name and a config
175	    /// object, whose props type is the one declared in this file for that tag (`interface CenterProps extends
176	    /// HTMLChakraProps<"div">`). Nothing here names a library; calls that build elements rather than components
177	    /// (`createElement("div", { ... })`) are excluded by name, as React's own API.
178	    pub(super) fn try_record_tagged_factory<'a>(
179	        &mut self,
180	        decl: &super::component::Binding<'_, 'a>,
181	        name: &str,
182	    ) -> bool {
183	        let Some(init) = decl.init else { return false };
184	        let Expression::CallExpression(call) = super::component::peel_expr(init) else { return false };
185	        if call.type_arguments.is_some() {
186	            return false;
187	        }
188	        let [tag, config] = call.arguments.as_slice() else { return false };
189	        let Some(Expression::StringLiteral(tag)) = tag.as_expression().map(super::component::peel_expr) else {
190	            return false;
191	        };
192	        let tag_name = tag.value.as_str().map(str::to_owned);
193	        let is_tag = tag.value.as_str().is_some_and(|name| {
194	            name.starts_with(|c: char| c.is_ascii_lowercase())
195	                && name.chars().all(|c| c.is_ascii_alphanumeric() || c == '-')
196	        });
197	        let has_config =
198	            matches!(config.as_expression().map(super::component::peel_expr), Some(Expression::ObjectExpression(_)));
199	        let Some(callee) = self.extract_callee_name(call) else { return false };
200	        let element_builder = match callee.rsplit_once('.') {
201	            Some((receiver, name)) => super::evidence::is_element_factory_name(name, Some(receiver), &*self),
202	            None => super::evidence::is_element_factory_name(&callee, None, &*self),
203	        };
204	        if !is_tag || !has_config || element_builder {
205	            return false;
206	        }
207	        let (description, tags) = self.find_jsdoc_with_tags(decl.span.start);
208	        self.pending_wrappers.push(PendingWrapper {
209	            name: name.to_owned(),
210	            needs_payload: false,
211	            tag: tag_name,
212	            type_args: Vec::new(),
213	            callee: None,
214	            rule: DetectionRule::TaggedFactory,
215	            description,
216	            tags,
217	            span: decl.span,
218	        });
219	        true
220	    }
221	
222	    /// Whether a generic call names the props type of the component it builds in its type arguments, as in
223	    /// `withContext<HTMLDivElement, OverlayProps>(BaseOverlay, …)`. The call's own props then replace those of the
224	    /// component it receives.
225	    pub(super) fn call_names_props_type<'a>(&mut self, call: &CallExpression<'a>) -> bool {
226	        let Some(type_arguments) = call.type_arguments.as_ref() else { return false };
227	        let type_args: Vec<WrapperTypeArg> = type_arguments
228	            .params
229	            .iter()
230	            .map(|ty| WrapperTypeArg { reference: self.extract_type_name_from_type(ty) })
231	            .collect();
232	        matches!(self.select_wrapper_props(&type_args), PropsSelection::Found { from_payload: false, .. })
233	    }
234	
235	    /// Turn the recorded candidates into mappings, now that every declaration in the file is known.
236	    pub(super) fn promote_wrapper_calls(&mut self) {
237	        let pending_wrappers = std::mem::take(&mut self.pending_wrappers);
238	        let tag_uses =
239	            |tag: &str| pending_wrappers.iter().filter(|pending| pending.tag.as_deref() == Some(tag)).count();
240	        let shared_tags: Vec<bool> = pending_wrappers
241	            .iter()
242	            .map(|pending| pending.tag.as_deref().is_some_and(|tag| tag_uses(tag) > 1))
243	            .collect();
244	        // A tagged factory takes the props type no other component in the file takes, so every other candidate is
245	        // promoted first, in source order: `StyledGroup = chakra("div", …)` comes before `Group = withContext<…,
246	        // GroupProps>(StyledGroup)` and would otherwise take `GroupProps` before `Group` claims it.
247	        let (tagged, others): (Vec<_>, Vec<_>) =
248	            pending_wrappers.into_iter().zip(shared_tags).partition(|(pending, _)| pending.tag.is_some());
249	        for (pending, shared_tag) in others.into_iter().chain(tagged) {
250	            // The anonymous default export is no binding of its name, so a binding of that name is no reason to skip it.
251	            let bound = self.anonymous_default != Some(pending.span.start);
252	            if bound && self.data.component_mappings.iter().any(|m| m.is_binding_named(&pending.name)) {
253	                continue;
254	            }
255	            if let Some(tag) = &pending.tag {
256	                let Some((props_name, props_args)) = self.tagged_factory_props(&pending.name, tag, shared_tag) else {
257	                    self.record_skip(
258	                        DiagnosticCode::SkippedCandidate,
259	                        format!(
260	                            "'{}' is built from a tag and a config object, but no props type declared in this file gives the tag \"{tag}\"",
261	                            pending.name
262	                        ),
263	                        pending.span,
264	                    );
265	                    continue;
266	                };
267	                self.data.component_mappings.push(
268	                    ComponentMapping::new(
269	                        pending.name,
270	                        props_name,
271	                        self.file_path.clone(),
272	                        pending.span.start,
273	                        pending.span.end,
274	                        pending.rule,
275	                    )
276	                    .with_props_type_args(props_args)
277	                    .with_doc(pending.description, pending.tags),
278	                );
279	                continue;
280	            }
281	            let selected = match self.select_wrapper_props(&pending.type_args) {
282	                PropsSelection::Found { name, args, from_payload } if from_payload || !pending.needs_payload => {
283	                    Some((name, args))
284	                }
285	                PropsSelection::UnusablePayload { alias } => {
286	                    self.record_skip(
287	                        DiagnosticCode::SkippedCandidate,
288	                        format!(
289	                            "'{}' is built from the factory payload '{alias}', whose `props` member is not a named type",
290	                            pending.name
291	                        ),
292	                        pending.span,
293	                    );
294	                    continue;
295	                }
296	                PropsSelection::Found { .. } | PropsSelection::None => None,
297	            };
298	            let Some((props_name, props_args)) = selected else {
299	                self.record_skip(
300	                    DiagnosticCode::SkippedCandidate,
301	                    format!(
302	                        "'{}' looks like a component built by a wrapper call, but none of its type arguments names {}",
303	                        pending.name,
304	                        if pending.needs_payload {
305	                            "a factory payload, which a tag-name argument needs"
306	                        } else {
307	                            "a props type declared in this file or ending in Props"
308	                        }
309	                    ),
310	                    pending.span,
311	                );
312	                continue;
313	            };
314	            let mut mapping = ComponentMapping::new(
315	                pending.name,
316	                props_name,
317	                self.file_path.clone(),
318	                pending.span.start,
319	                pending.span.end,
320	                pending.rule,
321	            )
322	            .with_props_type_args(props_args)
323	            .with_doc(pending.description, pending.tags);
324	            if let Some(callee) = pending.callee {
325	                mapping = mapping.with_wrapper_callee(callee);
326	            }
327	            if !bound {
328	                mapping = mapping.without_binding();
329	            }
330	            self.data.component_mappings.push(mapping);
331	        }
332	    }
