334	    /// The props type a tagged factory builds from: the interface or alias declared in this file whose heritage or body
335	    /// gives the factory's tag as a type argument, `interface CenterProps extends HTMLChakraProps<"div">` for
336	    /// `chakra("div", …)`, or extends the element's own attributes. Of several, or when other factories in the file
337	    /// share the tag, the one named for the binding. A props type another component in the file takes is not a candidate.
338	    fn tagged_factory_props(
339	        &self,
340	        binding: &str,
341	        tag: &str,
342	        shared_tag: bool,
343	    ) -> Option<(TypeName, Vec<CollectedType>)> {
344	        let prefix = format!("{}:", self.file_path);
345	        let mut found: Vec<TypeName> = Vec::new();
346	        for interface in self.data.interfaces.values().filter(|interface| interface.file_path == self.file_path) {
347	            if interface.extends.iter().any(|extends| extends_gives_tag(extends, tag)) {
348	                found.push(interface.name.clone());
349	            }
350	        }
351	        for (key, alias) in &self.data.type_aliases {
352	            let Some(name) = key.strip_prefix(&prefix) else { continue };
353	            if alias_gives_tag(alias, tag) {
354	                found.push(TypeName::from(name));
355	            }
356	        }
357	        // A props type another component in the file already takes belongs to that component: `StyledGroup =
358	        // chakra("div", …)` is the private recipe `Group` is built on, not a component with `GroupProps`.
359	        found.retain(|name| !self.data.component_mappings.iter().any(|mapping| mapping.props_type_name == *name));
360	        found.sort();
361	        found.dedup();
362	        let wanted = format!("{binding}Props");
363	        let chosen = match found.as_slice() {
364	            [only] if !shared_tag => only.clone(),
365	            _ => found.into_iter().find(|name| name.as_str() == wanted)?,
366	        };
367	        Some((chosen, Vec::new()))
368	    }
