370	    /// The callee of a generic call that builds a component, and its type arguments, for the props its result type
371	    /// adds (`resolver::callee`). `None` for a call without type arguments.
372	    pub(super) fn wrapper_callee<'a>(&mut self, call: &CallExpression<'a>) -> Option<WrapperCallee> {
373	        let type_arguments = call.type_arguments.as_ref()?;
374	        let name = self.extract_callee_name(call)?;
375	        Some(WrapperCallee {
376	            name: name.as_str().into(),
377	            type_args: type_arguments.params.iter().map(|ty| self.ts_type_to_collected(ty)).collect(),
378	        })
379	    }
380	
381	    /// Record a function's result when a call to it can build a component: a generic function's annotated, asserted,
382	    /// or single returned local factory result, and any function's returned local asserted to a type
383	    /// (`return Calendar` with `const Calendar = forwardRef(Inner) as ForwardRefExoticComponent<P>`) or returned
384	    /// rendering function (`return function Loader(props: P) { return <svg /> }`). A wrapper or factory call to it then
385	    /// gets the props that result adds (`resolver::callee`).
386	    pub(super) fn record_function_result<'a>(&mut self, func: &Function<'a>) {
387	        let Some(id) = &func.id else { return };
388	        self.record_result_of(
389	            id.name.as_str(),
390	            func.type_parameters.as_deref(),
391	            func.return_type.as_deref(),
392	            func.body.as_deref(),
393	        );
394	    }
395	
396	    /// `const generateCalendar = <T,>(config: C<T>) => { ... }`: the same, for a function bound to a name.
397	    pub(super) fn record_bound_function_result<'a>(&mut self, name: &str, init: &Expression<'a>) {
398	        match init.without_parentheses() {
399	            Expression::ArrowFunctionExpression(f) => {
400	                // An expression body returns nothing a statement could name.
401	                if let ArrowFunctionBody::FunctionBody(body) = &f.body {
402	                    self.record_result_of(name, f.type_parameters.as_deref(), f.return_type.as_deref(), Some(body));
403	                }
404	            }
405	            Expression::FunctionExpression(f) => {
406	                self.record_result_of(name, f.type_parameters.as_deref(), f.return_type.as_deref(), f.body.as_deref());
407	            }
408	            _ => {}
409	        }
410	    }
411	
412	    fn record_result_of<'a>(
413	        &mut self,
414	        name: &str,
415	        type_parameters: Option<&TSTypeParameterDeclaration<'a>>,
416	        return_type: Option<&TSTypeAnnotation<'a>>,
417	        body: Option<&FunctionBody<'a>>,
418	    ) {
419	        let generic = type_parameters.is_some();
420	        let declared = return_type.is_some();
421	        let (result, returned_call) = if let Some(annotation) = return_type {
422	            if !generic {
423	                return;
424	            }
425	            (self.ts_type_to_collected(&annotation.type_annotation), None)
426	        } else if let Some(ty) = asserted_return_type(body).filter(|_| generic) {
427	            (self.ts_type_to_collected(ty), None)
428	        } else if let Some(ty) = returned_local_asserted(body) {
429	            (self.ts_type_to_collected(ty), None)
430	        } else if let Some(function_type) = self.returned_rendering_function(body) {
431	            (function_type, None)
432	        } else if generic {
433	            (CollectedType::Unknown, returned_local_call(self, body))
434	        } else {
435	            return;
436	        };
437	        if matches!(result, CollectedType::Unknown) && returned_call.is_none() {
438	            return;
439	        }
440	        let type_params = super::type_param_names(type_parameters);
441	        let key = self.scoped_key(name);
442	        // A declared result type is written around the function; every other result is read from its body, whose
443	        // scope is known once the body has been walked (`finish`).
444	        let mut scope = self.current_scope();
445	        self.body_result_keys.retain(|(recorded, _)| *recorded != key);
446	        if let (false, Some(body)) = (declared, body) {
447	            self.body_result_keys.push((key.clone(), body.span.start));
448	            scope = DeclarationScope::default();
449	        }
450	        self.data.function_results.insert(key, FunctionResult { type_params, result, returned_call, scope });
451	    }
452	
453	    /// A single top-level `return function Loader(props: Props) { ... }` or `return (props: Props) => ...` that
454	    /// renders: a component built by the function, with a function type whose first parameter is the props.
455	    fn returned_rendering_function<'a>(&mut self, body: Option<&FunctionBody<'a>>) -> Option<CollectedType> {
456	        let mut returns = body?.statements.iter().filter_map(|statement| match statement {
457	            Statement::ReturnStatement(ret) => ret.argument.as_ref(),
458	            _ => None,
459	        });
460	        let only = returns.next()?;
461	        if returns.next().is_some() {
462	            return None;
463	        }
464	        let (params, shape) = match only.without_parentheses() {
465	            Expression::FunctionExpression(f) => (&f.params, FunctionShape::of_function(f)),
466	            Expression::ArrowFunctionExpression(f) => (&f.params, FunctionShape::of_arrow(f)),
467	            _ => return None,
468	        };
469	        let annotation = params.items.first()?.type_annotation.as_ref()?;
470	        if renders(&shape, &*self).is_err() {
471	            return None;
472	        }
473	        let props = self.ts_type_to_collected(&annotation.type_annotation);
474	        Some(CollectedType::Function {
475	            type_params: Vec::new(),
476	            params: vec![props],
477	            param_names: vec![None],
478	            param_kinds: Vec::new(),
479	            return_type: Box::new(CollectedType::Unknown),
480	        })
481	    }
482	
483	    /// Record `const Calendar = generateCalendar<Dayjs>(config)` and `const Loader = createLoader("x")` as a candidate:
484	    /// a PascalCase binding initialized with a call to a plain function. Nothing here knows what the function returns,
485	    /// which may be declared in another file; the candidate is a component only if the props can be read from the
486	    /// callee's recorded result, and goes unpublished otherwise (`resolver`). Calls to React's own APIs are other
487	    /// rules' business, and a constant name is never one.
488	    pub(super) fn try_record_factory_call<'a>(&mut self, decl: &super::component::Binding<'_, 'a>, name: &str) -> bool {
489	        let Some(init) = decl.init else { return false };
490	        let Expression::CallExpression(call) = super::component::peel_expr(init) else { return false };
491	        let Expression::Identifier(callee) = super::component::peel_expr(&call.callee) else { return false };
492	        // A rule that gave its reason for declining the call has already said what it is not.
493	        let explained = self.decline_reason.is_some() && !self.argument_declined;
494	        let element_builder = super::evidence::is_element_factory_name(callee.name.as_str(), None, &*self);
